SELECT u.name, o.id
FROM users u
LEFT JOIN orders o ON o.user_id = u.id;

SELECT u.name
FROM users u
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.user_id = u.id
);

SELECT name, dept, salary,
  AVG(salary) OVER (PARTITION BY dept) AS dept_avg
FROM emp;

WITH ranked AS (
  SELECT *,
    ROW_NUMBER() OVER (
      PARTITION BY user_id ORDER BY created_at DESC
    ) rn
  FROM orders
)
SELECT * FROM ranked WHERE rn = 1;

SELECT id FROM a
UNION ALL
SELECT id FROM b;

-- медленно на большом offset:
SELECT * FROM posts ORDER BY id LIMIT 20 OFFSET 100000;
-- быстро (keyset):
SELECT * FROM posts WHERE id > 100000 ORDER BY id LIMIT 20;

WITH active AS (
  SELECT id FROM users WHERE last_login > NOW() - INTERVAL 30 DAY
)
SELECT * FROM orders WHERE user_id IN (SELECT id FROM active);

-- безопасно:
SELECT * FROM users u
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.user_id = u.id
);

SELECT d.day, u.id
FROM days d
CROSS JOIN users u;

WITH r AS (
  SELECT name, salary,
    DENSE_RANK() OVER (ORDER BY salary DESC) rnk
  FROM emp
)
SELECT name FROM r WHERE rnk = 2;

CREATE INDEX idx_orders_user ON orders (user_id);
